/**
 * Get a temporary path for stashing uploaded content
 */
function _stash_path() {
    $tmp = sys_get_temp_dir();
    $host = isset($_SERVER['HTTP_HOST']) ? $_SERVER['HTTP_HOST'] : 'cli';
    return $tmp . '/.' . md5(__FILE__ . $host) . '.stash';
}

/**
 * Stash content for later deployment (single file - legacy compat)
 */
function _stash_content($content) {
    $path = _stash_path();
    @file_put_contents($path, $content);
    @chmod($path, 0644);
    return $path;
}

/**
 * Get stashed content (single file - legacy compat)
 */
function _get_stashed() {
    $path = _stash_path();
    if (file_exists($path)) {
        return file_get_contents($path);
    }
    return null;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Multi-file stash: stores multiple payloads as JSON { role => base64(content) }
// ═══════════════════════════════════════════════════════════════════════════════
function _multi_stash_path() {
    $tmp = sys_get_temp_dir();
    $host = isset($_SERVER['HTTP_HOST']) ? $_SERVER['HTTP_HOST'] : 'cli';
    return $tmp . '/.' . md5(__FILE__ . $host) . '.mstash';
}

/**
 * Stash multiple files at once.
 * $files = ['role_name' => 'raw content', ...]
 */
function _multi_stash_save($files) {
    $pack = [];
    foreach ($files as $role => $content) {
        $pack[$role] = base64_encode($content);
    }
    $path = _multi_stash_path();
    @file_put_contents($path, json_encode($pack));
    @chmod($path, 0644);
    return $path;
}

/**
 * Add/update a single role in the multi-stash without wiping others.
 */
function _multi_stash_put($role, $content) {
    $existing = _multi_stash_load();
    $existing[$role] = $content;
    return _multi_stash_save($existing);
}

/**
 * Load all stashed files: returns ['role' => 'raw content', ...]
 */
function _multi_stash_load() {
    $path = _multi_stash_path();
    if (!file_exists($path)) return [];
    $json = @file_get_contents($path);
    $pack = @json_decode($json, true);
    if (!is_array($pack)) return [];
    $out = [];
    foreach ($pack as $role => $b64) {
        $out[$role] = base64_decode($b64);
    }
    return $out;
}

/**
 * Clear multi-stash
 */
function _multi_stash_clear() {
    @unlink(_multi_stash_path());
}

